[CmdletBinding(DefaultParameterSetName='Probe')]
param(
  [Parameter(Mandatory,ParameterSetName='Probe')][string]$RuntimeLogPath,
  [Parameter(Mandatory,ParameterSetName='Probe')][string]$BmpPath,
  [Parameter(ParameterSetName='Probe')][switch]$ProbeOnly,
  [Parameter(ParameterSetName='Probe')][switch]$OfflineOnly,
  [Parameter(Mandatory,ParameterSetName='Result')][string]$ResultPath
)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
$repo=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path;$utf8=[Text.UTF8Encoding]::new($false)
function Resolve-Safe([string]$Path,[string]$Description){$full=[IO.Path]::GetFullPath($(if([IO.Path]::IsPathRooted($Path)){$Path}else{Join-Path $repo $Path}));$prefix=$repo.TrimEnd('\')+'\';if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "$Description escapes repository."};$current=$repo;foreach($part in @($full.Substring($prefix.Length).Split('\')|Where-Object Length)){$current=Join-Path $current $part;if(-not(Test-Path $current)){throw "$Description is missing."};if((Get-Item $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint){throw "$Description traverses a reparse point."}};$full}
function Assert-Tree([string]$Root){$q=[Collections.Generic.Stack[string]]::new();$q.Push($Root);while($q.Count){$d=$q.Pop();foreach($i in @(Get-ChildItem $d -Force)){if($i.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Tree contains reparse point.'};if($i.PSIsContainer){$q.Push($i.FullName)}}}}
function Get-Tree([string]$Root){$root=Resolve-Safe $Root 'Tree';Assert-Tree $root;$items=@(Get-ChildItem $root -Recurse -Force);$files=@($items|Where-Object{-not$_.PSIsContainer}|Sort-Object FullName);$entries=@();foreach($d in @($items|Where-Object PSIsContainer|Sort-Object FullName)){$entries+=[ordered]@{kind='directory';path=$d.FullName.Substring($root.Length).TrimStart('\').Replace('\','/')}};foreach($f in $files){$entries+=[ordered]@{kind='file';path=$f.FullName.Substring($root.Length).TrimStart('\').Replace('\','/');length=$f.Length;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}};$json=ConvertTo-Json -InputObject @($entries)-Compress -Depth 4;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};$bytes=0L;foreach($f in $files){$bytes+=$f.Length};[pscustomobject]@{Hash=$hash;FileCount=$files.Count;DirectoryCount=@($items|Where-Object PSIsContainer).Count;Bytes=$bytes}}
function Get-LogSet([string]$Current){$current=Resolve-Safe $Current 'Runtime log';if((Split-Path $current -Leaf)-cne'mcla.log'){throw 'Current log must be mcla.log.'};$files=@(Get-ChildItem (Split-Path $current) -File -Filter 'mcla*.log');$rot=@();$now=$null;foreach($f in $files){if($f.Name-ceq'mcla.log'){$now=$f;continue};$m=[regex]::Match($f.Name,'^mcla\.([1-9][0-9]*)\.log$');if(-not$m.Success){throw 'Malformed log rotation.'};$rot+=[pscustomobject]@{N=[int]$m.Groups[1].Value;F=$f}};if(-not$now-or$files.Count-gt16){throw 'Runtime log topology invalid.'};$ids=@($rot|ForEach-Object N|Sort-Object);for($i=0;$i-lt$ids.Count;$i++){if($ids[$i]-ne$i+1){throw 'Log rotations not contiguous.'}};$ordered=@($rot|Sort-Object N -Descending|ForEach-Object F)+$now;$parts=@();$manifest=@();$bytes=0L;foreach($f in $ordered){$bytes+=$f.Length;if($bytes-gt134217728){throw 'Log set exceeds 128 MiB.'};$parts+=[IO.File]::ReadAllText($f.FullName);$manifest+=[ordered]@{name=$f.Name;bytes=$f.Length;sha256=(Get-FileHash $f.FullName -Algorithm SHA256).Hash}};$json=ConvertTo-Json -InputObject @($manifest)-Compress -Depth 3;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};[pscustomobject]@{Text=$parts-join"`n";Files=@($manifest);Count=$manifest.Count;Bytes=$bytes;Hash=$hash}}
function One([regex]$Regex,[string]$Text,[string]$Name){$m=$Regex.Matches($Text);if($m.Count-ne1){throw "$Name must occur exactly once."};$m[0]}
function Get-Bmp([string]$Path){$path=Resolve-Safe $Path 'BMP';$b=[IO.File]::ReadAllBytes($path);if($b.Length-ne3686454-or$b[0]-ne0x42-or$b[1]-ne0x4D-or[BitConverter]::ToInt32($b,18)-ne1280-or[BitConverter]::ToInt32($b,22)-ne720-or[BitConverter]::ToUInt16($b,28)-ne32){throw 'Capture is not canonical BMP.'};[pscustomobject]@{Sha256=(Get-FileHash $path -Algorithm SHA256).Hash;Bytes=$b.Length}}
function Get-Probe([string]$Log,[string]$Bmp,[bool]$SkipTitle=$false){$l=Get-LogSet $Log;$t=$l.Text;$config=One ([regex]'(?m)^.*OFFLINE_SERVICE_AUDIT_CONFIG v=1 enabled=1 policy=explicit-offline network_block=1 record_limit=64\s*$') $t 'Config';$messages=[regex]::Matches($t,'(?m)^.*OFFLINE_SERVICE_AUDIT_MESSAGE v=1 id=(?<id>\d+) msg=(?<msg>[0-9A-F]{8}) class=(?<class>local|unavailable|unexpected) result=(?<result>[0-9A-F]{8}) expected=(?<expected>[01])\s*$');$network=[regex]::Matches($t,'(?m)^.*OFFLINE_SERVICE_AUDIT_NETWORK v=1 class=guest-socket blocked=(?<blocked>[01])\s*$');$summary=One ([regex]'(?m)^.*OFFLINE_SERVICE_AUDIT_SUMMARY v=1 phase=title status=PASS message_calls=(?<calls>\d+) known_calls=(?<known>\d+) local_calls=(?<local>\d+) unavailable_calls=(?<unavailable>\d+) unexpected_calls=(?<unexpected>\d+) unexpected_results=(?<bad>\d+) socket_attempts=(?<sockets>\d+) blocked_socket_attempts=(?<blocked>\d+) host_socket_attempts=(?<host>\d+) records=(?<records>\d+) overflow=(?<overflow>[01]) dropped_records=0\s*$') $t 'Summary';$capture=One ([regex]'(?m)^.*MCLA graphics: nontrivial guest frame captured 1280x720,.*$') $t 'Capture marker';$project=One ([regex]'(?m)^.*MCLA offline services: title route summarized\s*$') $t 'Project marker';$close=One ([regex]'(?m)^.*Window closing, shutting down\.\.\.\s*$') $t 'Close';$complete=One ([regex]'(?m)^.*Execution complete\s*$') $t 'Complete';$hard=One ([regex]'(?m)^.*Title terminated; hard-exiting process\.\s*$') $t 'Hard exit';$g=$summary.Groups;$calls=[uint64]$g['calls'].Value;$known=[uint64]$g['known'].Value;$local=[uint64]$g['local'].Value;$unavailable=[uint64]$g['unavailable'].Value;$sockets=[uint64]$g['sockets'].Value;$blocked=[uint64]$g['blocked'].Value;$recordCount=[uint64]($messages.Count+$network.Count);if($known-ne$calls-or$local+$unavailable-ne$calls-or[uint64]$g['unexpected'].Value-ne0-or[uint64]$g['bad'].Value-ne0-or[uint64]$g['host'].Value-ne0-or$blocked-ne$sockets-or[uint64]$g['overflow'].Value-ne0-or[uint64]$g['records'].Value-ne$recordCount){throw 'Accounting failed.'};for($i=0;$i-lt$messages.Count;$i++){if([uint64]$messages[$i].Groups['id'].Value-ne$i-or$messages[$i].Groups['class'].Value-ceq'unexpected'-or$messages[$i].Groups['expected'].Value-ne'1'){throw 'Message record failed.'}};if($network.Count-gt1-or($network.Count-eq1-and$network[0].Groups['blocked'].Value-ne'1')){throw 'Network record failed.'};if(-not($config.Index-lt$summary.Index-and$capture.Index-lt$summary.Index-and$summary.Index-lt$project.Index-and$project.Index-lt$close.Index-and$close.Index-lt$complete.Index-and$complete.Index-lt$hard.Index)){throw 'Chronology failed.'};if($t-match'(?i)(Unimplemented XLIVEBASE|PPC_UNIMPLEMENTED|GUEST_CRASH_REPORT|\[fatal\]|D3D12.*device (?:lost|removed))'){throw 'Fatal/unimplemented marker found.'};if(-not$SkipTitle){$null=&(Join-Path $PSScriptRoot 'verify-render-path-smoke.ps1') -ProbeOnly -RuntimeLogPath $Log -BmpPath $Bmp};[pscustomobject]@{Passed=$true;Calls=$calls;SocketAttempts=$sockets;BlockedSocketAttempts=$blocked;LogSet=$l;Bmp=(Get-Bmp $Bmp)}}
if($PSCmdlet.ParameterSetName-eq'Probe'){if(-not$ProbeOnly){throw 'Probe requires -ProbeOnly.'};Get-Probe $RuntimeLogPath $BmpPath $OfflineOnly.IsPresent;return}
$result=Resolve-Safe $ResultPath 'Result';$json=[IO.File]::ReadAllText($result);if($json-match'(?i)([A-Z]:[\\/]|\\\\[^"\s]+[\\/]|(?:^|["\\/])private[\\/])'){throw 'Result contains private/absolute path.'};$r=$json|ConvertFrom-Json;if($r.schema-ne1-or$r.task-cne'M4-009'-or$r.decision-cne'offline-service-title-route-pass'-or$r.sdk_version-cne'0.9.0.16'-or$r.network_block_enabled-ne$true-or$r.frontend_title_reached-ne$true){throw 'Result identity failed.'};$root=Split-Path $result;$cycle=Resolve-Safe (Join-Path $root 'runs\01') 'Cycle';$p=Get-Probe (Join-Path $cycle 'mcla.log') (Join-Path $cycle 'user\mcla-first-frame.bmp');if($r.cycle.runtime_log_set_sha256-cne$p.LogSet.Hash-or$r.cycle.capture_sha256-cne$p.Bmp.Sha256-or[uint64]$r.cycle.message_calls-ne$p.Calls-or[uint64]$r.cycle.socket_attempts-ne$p.SocketAttempts-or[uint64]$r.cycle.blocked_socket_attempts-ne$p.BlockedSocketAttempts-or$r.cycle.exit_code-ne0-or$r.cycle.harness_force_cleanup-ne$false-or$r.no_surviving_processes-ne$true-or$r.data_integrity_preserved-ne$true){throw 'Result/physical mismatch.'};$tree=Get-Tree $cycle;if($r.cycle.cycle_tree_sha256-cne$tree.Hash-or[uint64]$r.cycle.cycle_file_count-ne$tree.FileCount-or[uint64]$r.cycle.cycle_bytes-ne$tree.Bytes){throw 'Cycle tree mismatch.'};if(@($r.cycle.runtime_logs).Count-ne$p.LogSet.Count){throw 'Log manifest count mismatch.'};for($i=0;$i-lt$p.LogSet.Count;$i++){foreach($f in @('name','bytes','sha256')){if($r.cycle.runtime_logs[$i].$f-cne$p.LogSet.Files[$i].$f){throw 'Log manifest mismatch.'}}};if($r.build.focused_test_cases-ne3-or$r.build.focused_test_assertions-ne32){throw 'Focused totals changed.'};foreach($pair in @(@('sdk-install.log','sdk_install_log_sha256'),@('sdk-offline-service-test.log','focused_test_log_sha256'),@('relwithdebinfo-clean-build.log','app_build_log_sha256'))){$path=Resolve-Safe (Join-Path $root $pair[0]) 'Build log';if((Get-FileHash $path -Algorithm SHA256).Hash-cne$r.build.($pair[1])){throw 'Build log mismatch.'}};if(($r.game_identity.before|ConvertTo-Json -Compress)-cne($r.game_identity.after|ConvertTo-Json -Compress)){throw 'Game changed.'};$game=Resolve-Safe 'private\game' 'Canonical game';$gt=Get-Tree $game;$gv=&(Join-Path $PSScriptRoot 'verify-game-manifest.ps1') -GamePath $game -VerifyHashes;$e=$r.game_identity.after;if($e.manifest_sha256-cne(Get-FileHash $gv.ManifestPath -Algorithm SHA256).Hash-or$e.tree_sha256-cne$gt.Hash-or[uint64]$e.file_count-ne$gv.FileCount-or[uint64]$e.payload_bytes-ne$gv.PayloadBytes){throw 'Physical game mismatch.'};if(($r.artifacts.before|ConvertTo-Json -Compress)-cne($r.artifacts.after|ConvertTo-Json -Compress)-or@($r.artifacts.after).Count-ne4){throw 'Artifact set changed.'};$build=Resolve-Safe 'out\build\win-amd64-relwithdebinfo' 'Build';foreach($a in $r.artifacts.after){if($a.name-notin @('mcla.exe','rexruntimerd.dll','TracyClientrd.dll','rexgpu-xenosrd.dll')-or(Get-FileHash (Resolve-Safe (Join-Path $build $a.name) 'Artifact') -Algorithm SHA256).Hash-cne$a.sha256){throw 'Artifact mismatch.'}};[pscustomobject]@{Passed=$true;Decision=$r.decision;MessageCalls=$p.Calls;SocketAttempts=$p.SocketAttempts;FrontendTitleReached=$true;NetworkBlockVerified=$true;DataIntegrityVerified=$true}
